import app from 'flarum/admin/app';
import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import CriterionRow from './CriterionRow';
import FieldsEditor from './FieldsEditor';
import { shown, t, tx } from './util';
/** One category: its details, its fields to rate (MyBB "fields") and its product details. */
export default class CategoryEditor extends Component {
  draft = '';
  view() {
    const {
      category
    } = this.attrs;
    return m("div", null, this.details(category), this.criteria(category), m(FieldsEditor, {
      category: category,
      save: attrs => this.save(attrs)
    }), m("section", {
      className: "CRAdmin-section CRAdmin-danger"
    }, m(Button, {
      className: "Button Button--danger",
      icon: "far fa-trash-can",
      onclick: () => this.remove()
    }, t('categories.delete'))));
  }
  save(attrs) {
    return this.attrs.category.save(attrs).then(() => m.redraw()).catch(shown);
  }
  details(category) {
    const parents = this.attrs.categories.filter(c => !c.parentId() && c !== category);
    return m("section", {
      className: "CRAdmin-section"
    }, m("h3", null, t('categories.details')), m("div", {
      className: "CRAdmin-grid"
    }, this.text(tx('categories.name'), category.name(), v => this.save({
      name: v
    })), this.text(tx('categories.icon'), category.icon() || '', v => this.save({
      icon: v || null
    }), 'fas fa-cut'), this.text(tx('categories.color'), category.color() || '', v => this.save({
      color: v || null
    }), '#4d698e'), m("div", {
      className: "Form-group"
    }, m("label", null, t('categories.parent')), m("select", {
      className: "FormControl",
      value: category.parentId() ? String(category.parentId()) : '',
      onchange: e => this.save({
        parentId: Number(e.target.value) || null
      })
    }, m("option", {
      value: ""
    }, t('categories.top_level')), parents.map(p => m("option", {
      value: p.id()
    }, p.name()))))), this.text(tx('categories.description'), category.description() || '', v => this.save({
      description: v || null
    })));
  }
  text(label, value, onsave, placeholder = '') {
    return m("div", {
      className: "Form-group"
    }, m("label", null, label), m("input", {
      className: "FormControl",
      value: value,
      placeholder: placeholder,
      onchange: e => {
        const next = e.target.value.trim();
        if (next !== value) onsave(next);
      }
    }));
  }
  criteria(category) {
    const list = (category.criteria() || []).filter(Boolean).sort((a, b) => a.position() - b.position());
    const others = this.attrs.categories.filter(c => c !== category);
    return m("section", {
      className: "CRAdmin-section"
    }, m("h3", null, t('criteria.title')), m("p", {
      className: "helpText"
    }, t('criteria.help')), m("ul", {
      className: "CRAdmin-criteria"
    }, list.map((c, i) => m(CriterionRow, {
      key: c.id(),
      criterion: c,
      index: i,
      all: list,
      others: others,
      onchange: this.attrs.onchange
    }))), m("form", {
      className: "CRAdmin-add",
      onsubmit: e => {
        e.preventDefault();
        this.addCriterion(category);
      }
    }, m("input", {
      className: "FormControl",
      placeholder: tx('criteria.new_placeholder'),
      "aria-label": tx('criteria.new_placeholder'),
      value: this.draft,
      oninput: e => this.draft = e.target.value
    }), m(Button, {
      type: "submit",
      className: "Button",
      icon: "fas fa-plus",
      disabled: !this.draft.trim()
    }, t('criteria.add'))));
  }
  addCriterion(category) {
    const name = this.draft.trim();
    if (!name) return;
    app.store.createRecord('review-criteria').save({
      name,
      weight: 1,
      relationships: {
        category
      }
    }).then(() => {
      this.draft = '';
      this.attrs.onchange();
    }).catch(shown);
  }
  remove() {
    const {
      category
    } = this.attrs;
    if (!confirm(tx('categories.delete_confirm', {
      name: category.name()
    }))) return;
    category.delete().then(() => this.attrs.ondelete()).catch(shown);
  }
}