import app from 'flarum/admin/app';
export const EXT = 'ernestdefoe-community-reviews';
export const t = (key, params = {}) => app.translator.trans(`${EXT}.admin.${key}`, params);
export const tx = (key, params = {}) => app.translator.trans(`${EXT}.admin.${key}`, params, true);

/** POST to one of our API endpoints. */
export const post = (path, body) => app.request({
  method: 'POST',
  url: `${app.forum.attribute('apiUrl')}${path}`,
  body
});

/** A save or delete whose error app.request has already shown: nothing more to say. */
export const shown = () => {
  /* app.request already showed the error */
};