import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import { t, tx } from './util';
/** Product details (optional spec fields): asked for when a product is added, shown on its page. */
export default class FieldsEditor extends Component {
  fields() {
    return [...(this.attrs.category.itemFields() || [])];
  }
  commit(next) {
    this.attrs.save({
      itemFields: next
    });
  }
  change(index, patch) {
    this.commit(this.fields().map((f, i) => i === index ? {
      ...f,
      ...patch
    } : f));
  }
  view() {
    return m("section", {
      className: "CRAdmin-section"
    }, m("h3", null, t('fields.title')), m("p", {
      className: "helpText"
    }, t('fields.help')), this.fields().map((f, i) => this.row(f, i)), m(Button, {
      className: "Button",
      icon: "fas fa-plus",
      onclick: () => this.commit([...this.fields(), {
        key: '',
        label: tx('fields.new_label'),
        type: 'text',
        options: [],
        filter: false
      }])
    }, t('fields.add')));
  }
  row(f, i) {
    return m("div", {
      className: "CRAdmin-field"
    }, m("input", {
      className: "FormControl",
      value: f.label,
      "aria-label": tx('fields.label'),
      onchange: e => this.change(i, {
        label: e.target.value
      })
    }), m("select", {
      className: "FormControl",
      value: f.type,
      "aria-label": tx('fields.type'),
      onchange: e => this.change(i, {
        type: e.target.value
      })
    }, ['text', 'number', 'choice'].map(type => m("option", {
      value: type
    }, t(`fields.type_${type}`)))), f.type === 'choice' ? m("input", {
      className: "FormControl",
      value: f.options.join(', '),
      "aria-label": tx('fields.options'),
      placeholder: tx('fields.options'),
      onchange: e => this.change(i, {
        options: this.options(e.target.value)
      })
    }) : m("span", null), m(Button, {
      className: "Button Button--icon Button--flat",
      icon: "far fa-trash-can",
      "aria-label": tx('fields.delete'),
      onclick: () => this.commit(this.fields().filter((_, j) => j !== i))
    }));
  }
  options(value) {
    return value.split(',').map(o => o.trim()).filter(Boolean);
  }
}