import app from 'flarum/admin/app';
import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import { post, shown, t, tx } from './util';
/** One field to rate: its name, weight, order, MyBB's "Add to category…" copy, and delete. */
export default class CriterionRow extends Component {
  view() {
    const {
      criterion: c,
      index,
      all
    } = this.attrs;
    return m("li", {
      className: "CRAdmin-criterion"
    }, m("input", {
      className: "FormControl",
      value: c.name(),
      "aria-label": tx('criteria.name'),
      onchange: e => c.save({
        name: e.target.value.trim()
      }).catch(shown)
    }), this.weight(c), m(Button, {
      className: "Button Button--icon Button--flat",
      icon: "fas fa-arrow-up",
      disabled: index === 0,
      "aria-label": tx('criteria.move_up'),
      onclick: () => this.move(-1)
    }), m(Button, {
      className: "Button Button--icon Button--flat",
      icon: "fas fa-arrow-down",
      disabled: index === all.length - 1,
      "aria-label": tx('criteria.move_down'),
      onclick: () => this.move(1)
    }), this.copy(c), m(Button, {
      className: "Button Button--icon Button--flat",
      icon: "far fa-trash-can",
      "aria-label": tx('criteria.delete'),
      onclick: () => this.remove()
    }));
  }
  weight(c) {
    return m("label", {
      className: "CRAdmin-weight"
    }, t('criteria.weight'), m("select", {
      className: "FormControl",
      value: String(c.weight()),
      onchange: e => c.save({
        weight: Number(e.target.value)
      }).catch(shown)
    }, ['1', '2', '3', '4', '5'].map(w => m("option", {
      value: w
    }, "\xD7", w))));
  }
  copy(c) {
    if (!this.attrs.others.length) return null;
    return m("select", {
      className: "FormControl CRAdmin-copy",
      "aria-label": tx('criteria.copy'),
      value: "",
      onchange: e => {
        const target = e.target.value;
        if (!target) return;
        post(`/review-criteria/${c.id()}/copy`, {
          categoryId: Number(target)
        }).then(() => {
          app.alerts.show({
            type: 'success'
          }, tx('criteria.copied'));
          this.attrs.onchange();
        }).catch(shown);
      }
    }, m("option", {
      value: ""
    }, t('criteria.copy')), this.attrs.others.map(o => m("option", {
      value: o.id()
    }, o.name())));
  }
  move(step) {
    const list = [...this.attrs.all];
    const [moved] = list.splice(this.attrs.index, 1);
    list.splice(this.attrs.index + step, 0, moved);
    post('/review-criteria/order', {
      order: list.map(x => Number(x.id()))
    }).then(() => this.attrs.onchange()).catch(() => this.attrs.onchange());
  }
  remove() {
    const c = this.attrs.criterion;
    if (!confirm(tx('criteria.delete_confirm', {
      name: c.name()
    }))) return;
    c.delete().then(() => this.attrs.onchange()).catch(shown);
  }
}