import ExtensionPage from 'flarum/admin/components/ExtensionPage';
import classList from 'flarum/common/utils/classList';
import CategoriesTab from './CategoriesTab';
import SettingsTab from './SettingsTab';
import MergeTab from './MergeTab';
import { t } from './util';
/**
 * The extension's admin page: Categories (with their fields to rate and product details), Settings (every MyBB
 * option) and Merge. The permission grid below it is core's (ExtensionPage keeps it).
 */
export default class ReviewsPage extends ExtensionPage {
  tab = 'categories';
  content() {
    return m("div", {
      className: "ExtensionPage-settings CRAdmin"
    }, m("div", {
      className: "container"
    }, m("nav", {
      className: "CRAdmin-tabs",
      role: "tablist"
    }, ['categories', 'settings', 'merge'].map(tab => m("button", {
      type: "button",
      role: "tab",
      "aria-selected": this.tab === tab ? 'true' : 'false',
      className: classList('CRAdmin-tab', this.tab === tab && 'is-active'),
      onclick: () => this.tab = tab
    }, t(`tabs.${tab}`)))), this.tab === 'categories' ? m(CategoriesTab, null) : this.tab === 'settings' ? m(SettingsTab, null) : m(MergeTab, null)));
  }
}