import app from 'flarum/admin/app';
import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import { post, shown, t, tx } from './util';

/** MyBB's ACP "Merge Products" by ID (the forum's item page also merges, by name). */
export default class MergeTab extends Component {
  source = '';
  target = '';
  merging = false;
  view() {
    return m("form", {
      className: "CRAdmin-section",
      onsubmit: e => {
        e.preventDefault();
        this.merge();
      }
    }, m("h3", null, t('merge.title')), m("p", {
      className: "helpText"
    }, t('merge.help')), m("div", {
      className: "CRAdmin-grid"
    }, m("div", {
      className: "Form-group"
    }, m("label", null, t('merge.source')), m("input", {
      className: "FormControl",
      type: "number",
      min: "1",
      value: this.source,
      oninput: e => this.source = e.target.value
    })), m("div", {
      className: "Form-group"
    }, m("label", null, t('merge.target')), m("input", {
      className: "FormControl",
      type: "number",
      min: "1",
      value: this.target,
      oninput: e => this.target = e.target.value
    }))), m(Button, {
      type: "submit",
      className: "Button Button--primary",
      loading: this.merging,
      disabled: !this.source || !this.target
    }, t('merge.submit')));
  }
  merge() {
    if (!confirm(tx('merge.confirm', {
      source: this.source,
      target: this.target
    }))) return;
    this.merging = true;
    post(`/review-items/${Number(this.source)}/merge`, {
      targetId: Number(this.target)
    }).then(() => {
      app.alerts.show({
        type: 'success'
      }, tx('merge.done'));
      this.source = '';
      this.target = '';
    }).catch(shown).finally(() => {
      this.merging = false;
      m.redraw();
    });
  }
}