import app from 'flarum/admin/app';
import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import classList from 'flarum/common/utils/classList';
import CategoryEditor from './CategoryEditor';
import { post, shown, t, tx } from './util';

/** MyBB's Categories page: the list in its order (up/down), a new category, and the selected one's editor. */
export default class CategoriesTab extends Component {
  categories = [];
  busy = true;
  selected = null;
  draft = '';
  oninit(vnode) {
    super.oninit(vnode);
    this.load();
  }
  load() {
    this.busy = true;
    app.store.find('review-categories').then(list => {
      this.categories = [...list].sort((a, b) => a.position() - b.position());
      this.selected = this.selected && this.categories.find(c => c.id() === this.selected.id()) || this.categories[0] || null;
    }).catch(() => app.alerts.show({
      type: 'error'
    }, tx('load_failed'))).finally(() => {
      this.busy = false;
      m.redraw();
    });
  }
  view() {
    if (this.busy) return m(LoadingIndicator, null);
    return m("div", {
      className: "CRAdmin-cats"
    }, m("div", {
      className: "CRAdmin-tree"
    }, m("ul", null, this.categories.map((c, i) => this.row(c, i))), !this.categories.length ? m("p", {
      className: "helpText"
    }, t('categories.empty')) : null, this.addForm()), m("div", {
      className: "CRAdmin-detail"
    }, this.selected ? m(CategoryEditor, {
      key: this.selected.id(),
      category: this.selected,
      categories: this.categories,
      onchange: () => this.load(),
      ondelete: () => (this.selected = null, this.load())
    }) : null));
  }
  row(c, i) {
    return m("li", {
      className: classList(this.selected === c && 'is-active', c.parentId() && 'is-child')
    }, m("button", {
      type: "button",
      className: "CRAdmin-treeItem",
      onclick: () => this.selected = c
    }, c.icon() ? m("i", {
      className: c.icon(),
      "aria-hidden": "true"
    }) : null, " ", c.name(), " ", m("span", {
      className: "CRAdmin-count"
    }, c.itemCount())), m("span", {
      className: "CRAdmin-move"
    }, m(Button, {
      className: "Button Button--icon Button--flat",
      icon: "fas fa-arrow-up",
      disabled: i === 0,
      "aria-label": tx('categories.move_up'),
      onclick: () => this.move(i, -1)
    }), m(Button, {
      className: "Button Button--icon Button--flat",
      icon: "fas fa-arrow-down",
      disabled: i === this.categories.length - 1,
      "aria-label": tx('categories.move_down'),
      onclick: () => this.move(i, 1)
    })));
  }
  addForm() {
    return m("form", {
      className: "CRAdmin-add",
      onsubmit: e => {
        e.preventDefault();
        this.add();
      }
    }, m("input", {
      className: "FormControl",
      placeholder: tx('categories.new_placeholder'),
      "aria-label": tx('categories.new_placeholder'),
      value: this.draft,
      oninput: e => this.draft = e.target.value
    }), m(Button, {
      type: "submit",
      className: "Button",
      icon: "fas fa-plus",
      disabled: !this.draft.trim()
    }, t('categories.add')));
  }
  move(index, step) {
    const list = [...this.categories];
    const [moved] = list.splice(index, 1);
    list.splice(index + step, 0, moved);
    this.categories = list;
    post('/review-categories/order', {
      order: list.map(c => Number(c.id()))
    }).then(() => this.load()).catch(() => this.load());
  }
  add() {
    const name = this.draft.trim();
    if (!name) return;
    app.store.createRecord('review-categories').save({
      name
    }).then(c => {
      this.draft = '';
      this.selected = c;
      this.load();
    }).catch(shown);
  }
}